  "$schema": "https://example.invalid/settings.schema.json",
  "lastChangelogVersion": "1.2.3",
  "extensionChangelogVersions": {
    "ext-a": "0.1.0"
  },
  "sessionDir": "~/oracle-sessions/",
  "defaultProvider": "anthropic",
  "defaultModel": "claude-oracle",
  "steeringMode": "all",
  "followUpMode": "all",
  "theme": "dark",
  "defaultThinkingLevel": "high",
  "modelThinkingLevels": {
    "anthropic/claude-oracle": "low"
  },
  "transport": "websocket",
  "sessionShareDestination": "radius",
  "compaction": {
    "enabled": false,
    "reserveTokens": 1000,
    "keepRecentTokens": 2000,
    "modelOverrides": {
      "anthropic/claude-oracle": {
        "reserveTokens": 3000
      }
    }
  },
  "branchSummary": {
    "reserveTokens": 4000,
    "skipPrompt": true
  },
  "retry": {
    "enabled": false,
    "maxRetries": 7,
    "baseDelayMs": 10,
    "maxAgentDelayMs": 99,
    "provider": {
      "maxRetryDelayMs": 1234
    }
  },
  "httpIdleTimeoutMs": 45000,
  "websocketConnectTimeoutMs": 5000,
  "cacheWarming": "idle",
  "hideThinkingBlock": true,
  "showCacheMissNotices": true,
  "externalEditor": "oracle-editor --wait",
  "shellPath": "~/bin/oracle-sh",
  "quietStartup": "header",
  "defaultProjectTrust": "always",
  "shellCommandPrefix": "set -e",
  "npmCommand": [
    "pnpm",
    "--silent"
  ],
  "collapseChangelog": true,
  "enableInstallTelemetry": false,
  "enableAnalytics": true,
  "trackingId": "tracking-oracle",
  "deviceId": "device-oracle",
  "packages": [
    "npm:oracle-a",
    {
      "source": "git:oracle-b",
      "extensions": [
        "x"
      ]
    }
  ],
  "extensions": [
    "./ext-global"
  ],
  "skills": [
    "./skills-global"
  ],
  "prompts": [
    "./prompts-global"
  ],
  "themes": [
    "./themes-global"
  ],
  "enableSkillCommands": false,
  "thinkingBudgets": {
    "low": 1000,
    "high": 9000
  },
  "terminal": {
    "showImages": false,
    "imageWidthCells": 33.7,
    "clearOnShrink": true,
    "showTerminalProgress": true,
    "images": "kitty",
    "trueColor": false,
    "hyperlinks": true
  },
  "tuiMode": "regular",
  "fullscreenExitOutput": "resume-hint",
  "fullscreenScrollbar": "always",
  "fullscreenCopyOnSelect": false,
  "fullscreenWheelScrollLines": 250,
  "images": {
    "autoResize": false,
    "blockImages": true
  },
  "enabledModels": [
    "anthropic/*",
    "openai/gpt-*"
  ],
  "defaultTools": [
    "read",
    "grep"
  ],
  "doubleEscapeAction": "fork",
  "treeFilterMode": "no-tools",
  "showHardwareCursor": true,
  "editorPaddingX": 2,
  "outputPad": 0,
  "autocompleteMaxVisible": 9,
  "markdown": {
    "codeBlockIndent": "    ",
    "mermaid": "final"
  },
  "warnings": {
    "anthropicExtraUsage": false
  },
  "oracleUnknownKey": {
    "nested": [
      1,
      "two"
    ],
    "keep": true
  }
}

